INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M01','math',1,'u1',ARRAY['M1-1-C1','M1-1-C2']::text[],'세면서 빠뜨리거나 같은 것을 두 번 센다','하나씩 짚으며(표시하며) 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M02','math',1,'u1',ARRAY['M1-1-C1','M1-1-C2']::text[],'수 읽기 혼동 (넷/사, 다섯/오 용법)','개수 세기는 하나·둘…, 번호는 일·이… 상황 구분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M03','math',1,'u1',ARRAY['M1-1-C1','M1-1-C2']::text[],'마지막에 센 수 = 전체 개수임을 모른다 (기수성)','"그래서 모두 몇 개?"를 다시 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M04','math',1,'u1',ARRAY['M1-1-C3']::text[],'몇째(순서)와 몇 개(개수)를 혼동한다','셋째는 한 명, 3개는 여러 개 — 그림 동그라미로 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M05','math',1,'u1',ARRAY['M1-1-C3']::text[],'세는 방향(왼쪽/오른쪽 기준)을 무시한다','화살표로 기준 방향 먼저 표시') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M06','math',1,'u1',ARRAY['M1-1-C4']::text[],'거꾸로 세기·이어 세기에서 순서가 흐트러진다','수 배열판 짚으며 오르내리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M07','math',1,'u1',ARRAY['M1-1-C5']::text[],'1만큼 더 큰/작은 방향을 반대로 잡는다','배열판에서 오른쪽=커짐 몸으로 익히기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
