INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M09','math',1,'u1',ARRAY['M1-1-C6','M1-1-C7']::text[],'0과 1을 혼동하거나 0의 크기 위치를 모른다','배열판 맨 앞에 0 놓기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M10','math',1,'u1',ARRAY['M1-1-C7']::text[],'개수가 아니라 늘어선 길이·퍼짐으로 비교한다','하나씩 짝지어(일대일 대응) 비교') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M11','math',1,'u1',ARRAY['M1-1-C7']::text[],'많다/적다 말을 반대로 쓴다','그림 가리키며 문장으로 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_basic#1','math',1,1,'u1','L01','g1_math_u1_L01_basic','lesson_basic','M1-1-C1',1,'mc','auto','사과는 모두 몇 개인가요?',ARRAY['M01']::text[],true,'{"seq":1,"concept":"M1-1-C1","difficulty":1,"kind":"mc","stem":"사과는 모두 몇 개인가요?","asset":{"type":"count_group","item":"🍎","n":3},"options":[{"t":"2","mis":"M01"},{"t":"3","correct":true},{"t":"4","mis":"M01"}],"explanation":["하나, 둘, 셋 — 사과는 3개예요.","2나 4는 하나를 빠뜨리거나 두 번 센 거예요.","막히면 사과를 하나씩 짚으며 세어 보세요."],"variant_rule":{"item":["🍎","🐤","⚽","🚗","🌼"],"n":[2,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_basic#2','math',1,1,'u1','L01','g1_math_u1_L01_basic','lesson_basic','M1-1-C1',1,'mc','auto','수 5를 바르게 읽은 것은 무엇인가요?',ARRAY['M02']::text[],true,'{"seq":2,"concept":"M1-1-C1","difficulty":1,"kind":"mc","stem":"수 5를 바르게 읽은 것은 무엇인가요?","options":[{"t":"다섯","correct":true},{"t":"넷","mis":"M02"},{"t":"둘","mis":"M02"}],"explanation":["5는 ''다섯''이라고 읽어요.","넷은 4, 둘은 2를 읽는 말이에요.","수와 읽는 말을 소리 내어 짝지어 보세요."],"variant_rule":{"n":[1,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_basic#3','math',1,1,'u1','L01','g1_math_u1_L01_basic','lesson_basic','M1-1-C1',1,'sa','auto','병아리의 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-1-C1","difficulty":1,"kind":"sa","stem":"병아리의 수를 숫자로 쓰세요.","asset":{"type":"count_group","item":"🐤","n":4},"answer":["4"],"explanation":["하나, 둘, 셋, 넷 — 4라고 써요.","''넷''이라고 읽고, 숫자로는 4예요.","숫자 쓰기가 헷갈리면 따라 쓰기 화면을 다시 보세요."],"variant_rule":{"item":["🐤","🍓","🎈"],"n":[1,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_basic#4','math',1,1,'u1','L01','g1_math_u1_L01_basic','lesson_basic','M1-1-C1',1,'match','auto','그림과 수를 알맞게 이어 보세요.','{}'::text[],true,'{"seq":4,"concept":"M1-1-C1","difficulty":1,"kind":"match","stem":"그림과 수를 알맞게 이어 보세요.","pairs":[{"l":{"type":"dots","n":2},"r":"2"},{"l":{"type":"dots","n":5},"r":"5"},{"l":{"type":"dots","n":1},"r":"1"}],"explanation":["점의 수를 세어 같은 수와 이어요.","●●는 둘이니까 2와 만나요.","점을 하나씩 짚으며 세면 틀리지 않아요."],"variant_rule":{"n_pool":[1,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_basic#5','math',1,1,'u1','L01','g1_math_u1_L01_basic','lesson_basic','M1-1-C1',2,'blank','auto','수를 세는 말이에요. 빈칸에 알맞은 말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_basic#6','math',1,1,'u1','L01','g1_math_u1_L01_basic','lesson_basic','M1-1-C1',2,'mc','auto','자동차의 수와 같은 것은 무엇인가요?',ARRAY['M01']::text[],true,'{"seq":6,"concept":"M1-1-C1","difficulty":2,"kind":"mc","stem":"자동차의 수와 같은 것은 무엇인가요?","asset":{"type":"count_group","item":"🚗","n":4},"options":[{"t":{"type":"dots","n":4},"correct":true},{"t":{"type":"dots","n":3},"mis":"M01"},{"t":{"type":"dots","n":5},"mis":"M01"}],"explanation":["자동차도 넷, 점도 넷 — 수가 같아요.","점 3개나 5개는 자동차 수와 달라요.","자동차 하나에 점 하나씩 짝지어 보세요."],"variant_rule":{"item":["🚗","🐟","✏️"],"n":[2,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_basic#7','math',1,1,'u1','L01','g1_math_u1_L01_basic','lesson_basic','M1-1-C1',2,'sa','auto','나비가 여기저기 날고 있어요. 나비는 모두 몇 마리인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-C1","difficulty":2,"kind":"sa","stem":"나비가 여기저기 날고 있어요. 나비는 모두 몇 마리인가요? 숫자로 쓰세요.","asset":{"type":"scatter_group","item":"🦋","n":5},"answer":["5"],"explanation":["흩어져 있어도 하나씩 세면 5마리예요.","퍼져 있다고 수가 달라지지 않아요.","센 나비에 표시를 하며 세어 보세요."],"variant_rule":{"item":["🦋","🐞","⭐"],"n":[3,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_basic#8','math',1,1,'u1','L01','g1_math_u1_L01_basic','lesson_basic','M1-1-C1',2,'ox','auto','물고기 🐟🐟의 수는 ''둘''입니다.',ARRAY['M10']::text[],true,'{"seq":8,"concept":"M1-1-C1","difficulty":2,"kind":"ox","stem":"물고기 🐟🐟의 수는 ''둘''입니다.","answer":"O","reason_options":[{"t":"하나, 둘 — 2마리라서","correct":true},{"t":"물고기가 크니까","mis":"M10"}],"explanation":["하나, 둘 — 물고기는 2마리, ''둘''이 맞아요.","크기는 수와 상관없어요. 수는 개수예요.","수를 셀 때는 크기 말고 개수만 보세요."],"variant_rule":{"item":["🐟","🍪"],"n":[1,5],"truth":["O","X"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_basic#9','math',1,1,'u1','L01','g1_math_u1_L01_basic','lesson_basic','M1-1-C1',2,'mc','auto','''셋''을 나타내는 그림은 무엇인가요?',ARRAY['M01']::text[],true,'{"seq":9,"concept":"M1-1-C1","difficulty":2,"kind":"mc","stem":"''셋''을 나타내는 그림은 무엇인가요?","options":[{"t":{"type":"count_group","item":"🌼","n":3},"correct":true},{"t":{"type":"count_group","item":"🌼","n":2},"mis":"M01"},{"t":{"type":"count_group","item":"🌼","n":4},"mis":"M01"}],"explanation":["꽃이 하나, 둘, 셋 있는 그림이 ''셋''이에요.","2송이·4송이는 셋이 아니에요.","말한 수만큼 손가락을 펴고 그림과 비교해 보세요."],"variant_rule":{"item":["🌼","🍩"],"n":[2,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
