INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_challenge#1','math',1,1,'u1','L01','g1_math_u1_L01_challenge','lesson_challenge','M1-1-C1',2,'sa','auto','별이 여기저기 흩어져 있어요. 별은 모두 몇 개인가요?','{}'::text[],true,'{"seq":1,"concept":"M1-1-C1","difficulty":2,"kind":"sa","stem":"별이 여기저기 흩어져 있어요. 별은 모두 몇 개인가요?","asset":{"type":"scatter_group","item":"⭐","n":5},"answer":["5"],"explanation":["표시하며 세면 별은 5개예요.","흩어져 있어도 개수는 그대로예요.","센 별에 하나씩 표시하며 세어 보세요."],"variant_rule":{"item":["⭐","🍁"],"n":[4,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_challenge#2','math',1,1,'u1','L01','g1_math_u1_L01_challenge','lesson_challenge','M1-1-C1',2,'sa','auto','수 4만큼 ○를 색칠했어요. 색칠한 ○는 몇 개여야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-C1","difficulty":2,"kind":"sa","stem":"수 4만큼 ○를 색칠했어요. 색칠한 ○는 몇 개여야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["4만큼이니까 ○를 4개 색칠해요.","수와 개수는 똑같이 맞춰요.","색칠하며 하나, 둘, 셋, 넷 소리 내어 보세요."],"variant_rule":{"n":[2,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_challenge#3','math',1,1,'u1','L01','g1_math_u1_L01_challenge','lesson_challenge','M1-1-C1',3,'mc','auto','병아리 5마리가 있었어요. 지금 3마리가 보여요. 상자 뒤에 숨은 병아리는 몇 마리인가요?',ARRAY['M03']::text[],true,'{"seq":3,"concept":"M1-1-C1","difficulty":3,"kind":"mc","stem":"병아리 5마리가 있었어요. 지금 3마리가 보여요. 상자 뒤에 숨은 병아리는 몇 마리인가요?","asset":{"type":"hidden_group","item":"🐤","visible":3,"total":5},"options":[{"t":"2","correct":true},{"t":"3","mis":"M03"},{"t":"5","mis":"M03"}],"options_note":"보이는 수를 답하거나 전체 수를 답하는 오류","explanation":["넷, 다섯 — 이어 세면 숨은 병아리는 2마리예요.","3은 보이는 병아리, 5는 전체 수예요.","보이는 3마리 다음부터 이어 세어 보세요."],"variant_rule":{"total":[3,5],"visible":[1,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_challenge#4','math',1,1,'u1','L01','g1_math_u1_L01_challenge','lesson_challenge','M1-1-C1',3,'error','auto','지우가 점 ●●●●● 를 세고 "넷!"이라고 했어요. 지우는 무엇을 잘못했나요?',ARRAY['M02','M03']::text[],true,'{"seq":4,"concept":"M1-1-C1","difficulty":3,"kind":"error","stem":"지우가 점 ●●●●● 를 세고 \"넷!\"이라고 했어요. 지우는 무엇을 잘못했나요?","options":[{"t":"점 하나를 빠뜨리고 세었어요","correct":true,"mis_target":"M01"},{"t":"점이 정말 넷이에요","mis":"M03"},{"t":"''다섯''을 넷이라고 읽었을 뿐 세기는 맞아요","mis":"M02"}],"explanation":["점은 다섯 개인데 하나를 빠뜨렸어요.","바르게 세면 하나~다섯, 5예요.","줄을 그어 가며 하나씩 세면 빠뜨리지 않아요."],"variant_rule":{"n":[4,5],"error_type":["skip","double"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_challenge#5','math',1,1,'u1','L01','g1_math_u1_L01_challenge','lesson_challenge','M1-1-C1',3,'data','auto','과일 가게 그림표예요. 딸기 칸에는 🍓가 4개, 바나나 칸에는 🍌가 2개 있어요. 바나나는 몇 개인가요?',ARRAY['M01','M05']::text[],true,'{"seq":5,"concept":"M1-1-C1","difficulty":3,"kind":"data","stem":"과일 가게 그림표예요. 딸기 칸에는 🍓가 4개, 바나나 칸에는 🍌가 2개 있어요. 바나나는 몇 개인가요?","asset":{"type":"picto_table","rows":[{"label":"딸기","item":"🍓","n":4},{"label":"바나나","item":"🍌","n":2}]},"options":[{"t":"2","correct":true},{"t":"4","mis":"M05"},{"t":"3","mis":"M01"}],"options_note":"다른 줄을 읽는 오류(M05는 기준 무시 계열로 임시 태그 — 검수 시 ''표 읽기 오개념'' 신설 검토)","explanation":["바나나 줄을 찾아 세면 2개예요.","4는 딸기 줄의 수예요.","묻는 것의 줄부터 손가락으로 짚어 보세요."],"variant_rule":{"items":[["🍓","🍌"],["🍎","🍇"]],"n":[1,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_challenge#6','math',1,1,'u1','L01','g1_math_u1_L01_challenge','lesson_challenge','M1-1-C1',3,'match','auto','같은 수끼리 이어 보세요. (숫자를 세는 말이나 점그림과 잇기)','{}'::text[],true,'{"seq":6,"concept":"M1-1-C1","difficulty":3,"kind":"match","stem":"같은 수끼리 이어 보세요. (숫자를 세는 말이나 점그림과 잇기)","pairs":[{"l":"5","r":"다섯"},{"l":"3","r":{"type":"dots","n":3}},{"l":"2","r":"둘"},{"l":"4","r":{"type":"dots","n":4}}],"explanation":["5는 다섯, 3은 ●●● — 모습만 다르고 같은 수예요.","숫자, 세는 말, 점그림은 서로 바꿔 쓸 수 있어요.","점을 세어 보고, 세는 말을 소리 내어 짝을 찾아요."],"variant_rule":{"n_pool":[1,5]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_challenge#7','math',1,1,'u1','L01','g1_math_u1_L01_challenge','lesson_challenge','M1-1-C1',3,'ox','auto','큰 수박 🍉 1개는 작은 딸기 🍓🍓🍓 3개보다 수가 많습니다.',ARRAY['M10']::text[],true,'{"seq":7,"concept":"M1-1-C1","difficulty":3,"kind":"ox","stem":"큰 수박 🍉 1개는 작은 딸기 🍓🍓🍓 3개보다 수가 많습니다.","answer":"X","reason_options":[{"t":"수는 크기가 아니라 개수로 세니까","correct":true},{"t":"수박이 더 크니까 많은 게 맞아요","mis":"M10"}],"explanation":["수박은 1개, 딸기는 3개 — 수는 딸기가 많아요.","크다고 수가 많은 게 아니에요. 수는 개수예요.","크기를 가리고 개수만 세어 보세요."],"variant_rule":{"big":["🍉","🐘"],"small":["🍓","🐜"],"n":[2,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_challenge#8','math',1,1,'u1','L01','g1_math_u1_L01_challenge','lesson_challenge','M1-1-C1',4,'sa','auto','점이 규칙대로 늘어나요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_challenge#9','math',1,1,'u1','L01','g1_math_u1_L01_challenge','lesson_challenge','M1-1-C1',4,'mc','auto','수수께끼예요. "나는 셋 바로 다음 수이고, 다섯 바로 앞의 수예요." 나는 누구일까요?',ARRAY['M06']::text[],true,'{"seq":9,"concept":"M1-1-C1","difficulty":4,"kind":"mc","stem":"수수께끼예요. \"나는 셋 바로 다음 수이고, 다섯 바로 앞의 수예요.\" 나는 누구일까요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M06"},{"t":"5","mis":"M06"}],"explanation":["셋 다음이면서 다섯 앞인 수는 4예요.","3과 5는 수수께끼의 힌트에 나온 수예요.","하나부터 차례로 말하며 두 힌트에 다 맞는지 확인해요."],"variant_rule":{"n":[2,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L01_challenge#10','math',1,1,'u1','L01','g1_math_u1_L01_challenge','lesson_challenge','M1-1-C1',4,'essay','teacher','왼쪽 상자에 공이 ●●, 오른쪽 상자에 공이 ●●● 있어요. 공은 모두 몇 개인지 쓰고, 어떻게 세었는지 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-C1","difficulty":4,"kind":"essay","stem":"왼쪽 상자에 공이 ●●, 오른쪽 상자에 공이 ●●● 있어요. 공은 모두 몇 개인지 쓰고, 어떻게 세었는지 말해 보세요.","answer_guide":{"answer":"5","scoring_points":["전체 개수 5를 말한다","이어 세기 또는 모두 세기 방법을 자기 말로 설명한다"],"example_answer":"모두 5개예요. 둘 다음에 셋, 넷, 다섯 하고 이어서 세었어요."},"grading":"teacher","explanation":["두 상자를 합쳐 세면 5개예요.","둘에서 이어 세거나 처음부터 다 세어도 돼요.","말로 설명하면 생각이 더 단단해져요."],"variant_rule":null}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_basic#1','math',1,1,'u1','L02','g1_math_u1_L02_basic','lesson_basic','M1-1-C2',1,'mc','auto','쿠키는 모두 몇 개인가요?',ARRAY['M01']::text[],true,'{"seq":1,"concept":"M1-1-C2","difficulty":1,"kind":"mc","stem":"쿠키는 모두 몇 개인가요?","asset":{"type":"count_group","item":"🍪","n":7},"options":[{"t":"6","mis":"M01"},{"t":"7","correct":true},{"t":"8","mis":"M01"}],"explanation":["하나, 둘, 셋, 넷, 다섯, 여섯, 일곱 — 쿠키는 7개예요.","6이나 8은 하나를 빠뜨리거나 두 번 센 거예요.","막히면 쿠키를 하나씩 짚으며 세어 보세요."],"variant_rule":{"item":["🍪","🐞","🎈","🚌","🍁"],"n":[6,9],"range":[1,9]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_basic#2','math',1,1,'u1','L02','g1_math_u1_L02_basic','lesson_basic','M1-1-C2',1,'mc','auto','수 8을 바르게 읽은 것은 무엇인가요?',ARRAY['M02']::text[],true,'{"seq":2,"concept":"M1-1-C2","difficulty":1,"kind":"mc","stem":"수 8을 바르게 읽은 것은 무엇인가요?","options":[{"t":"여덟","correct":true},{"t":"일곱","mis":"M02"},{"t":"여섯","mis":"M02"}],"explanation":["8은 ''여덟''이라고 읽어요.","일곱은 7, 여섯은 6을 읽는 말이에요.","수와 읽는 말을 소리 내어 짝지어 보세요."],"variant_rule":{"n":[6,9],"pool":[6,7,8,9]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_basic#3','math',1,1,'u1','L02','g1_math_u1_L02_basic','lesson_basic','M1-1-C2',1,'sa','auto','무당벌레의 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-1-C2","difficulty":1,"kind":"sa","stem":"무당벌레의 수를 숫자로 쓰세요.","asset":{"type":"count_group","item":"🐞","n":6},"answer":["6"],"explanation":["하나, 둘, 셋, 넷, 다섯, 여섯 — 6이라고 써요.","''여섯''이라고 읽고, 숫자로는 6이에요.","숫자 쓰기가 헷갈리면 따라 쓰기 화면을 다시 보세요."],"variant_rule":{"item":["🐞","🍩","⭐","🐟"],"n":[6,9],"range":[1,9]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
