INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_basic#6','math',1,1,'u1','L02','g1_math_u1_L02_basic','lesson_basic','M1-1-C2',2,'sa','auto','나뭇잎은 모두 몇 장인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-1-C2","difficulty":2,"kind":"sa","stem":"나뭇잎은 모두 몇 장인가요? 숫자로 쓰세요.","asset":{"type":"scatter_group","item":"🍁","n":9},"answer":["9"],"explanation":["흩어져 있어도 하나씩 짚으며 세면 9장이에요.","''아홉''이라고 읽고, 숫자로는 9예요.","센 것에 마음속으로 표시하며 세어 보세요."],"variant_rule":{"item":["🍁","🍓","🐤","⚽"],"n":[6,9],"range":[1,9]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_basic#7','math',1,1,'u1','L02','g1_math_u1_L02_basic','lesson_basic','M1-1-C2',2,'mc','auto','버스의 수와 같은 것은 무엇인가요?',ARRAY['M01']::text[],true,'{"seq":7,"concept":"M1-1-C2","difficulty":2,"kind":"mc","stem":"버스의 수와 같은 것은 무엇인가요?","asset":{"type":"count_group","item":"🚌","n":7},"options":[{"t":{"type":"dots","n":7},"correct":true},{"t":{"type":"dots","n":6},"mis":"M01"},{"t":{"type":"dots","n":8},"mis":"M01"}],"explanation":["버스를 세면 7대예요.","점도 일곱 개인 것을 찾아요.","수가 같으면 하나씩 짝지을 수 있어요."],"variant_rule":{"item":["🚌","🍎","🐘"],"n":[6,9],"range":[1,9]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_basic#8','math',1,1,'u1','L02','g1_math_u1_L02_basic','lesson_basic','M1-1-C2',2,'ox','auto','🐘🐘🐘🐘🐘🐘의 수는 ''여섯''입니다.',ARRAY['M10']::text[],true,'{"seq":8,"concept":"M1-1-C2","difficulty":2,"kind":"ox","stem":"🐘🐘🐘🐘🐘🐘의 수는 ''여섯''입니다.","answer":"O","reason_options":[{"t":"하나, 둘, 셋, 넷, 다섯, 여섯 — 6마리라서","correct":true},{"t":"코끼리가 크니까","mis":"M10"}],"explanation":["세어 보면 6마리, ''여섯''이에요.","맞는 말이에요.","수를 셀 때는 크기가 아니라 개수만 보세요."],"variant_rule":{"truth":["O","X"],"n":[6,9],"item":["🐘","🐤","🍎"],"range":[6,9]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_basic#9','math',1,1,'u1','L02','g1_math_u1_L02_basic','lesson_basic','M1-1-C2',2,'mc','auto','''여덟''을 나타내는 그림은 무엇인가요?',ARRAY['M02']::text[],false,'{"seq":9,"concept":"M1-1-C2","difficulty":2,"kind":"mc","stem":"''여덟''을 나타내는 그림은 무엇인가요?","options":[{"t":{"type":"dots","n":8},"correct":true},{"t":{"type":"dots","n":6},"mis":"M02"},{"t":{"type":"dots","n":9},"mis":"M02"}],"explanation":["여덟은 8이에요.","점을 세어 여덟 개인 것을 고르세요.","여섯·아홉과 헷갈리면 하나씩 짚으며 세어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
