INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_challenge#1','math',1,1,'u1','L02','g1_math_u1_L02_challenge','lesson_challenge','M1-1-C2',2,'sa','auto','개미는 모두 몇 마리인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-1-C2","difficulty":2,"kind":"sa","stem":"개미는 모두 몇 마리인가요? 숫자로 쓰세요.","asset":{"type":"scatter_group","item":"🐜","n":8},"answer":["8"],"explanation":["흩어진 그림도 하나씩 짚으며 세면 8마리예요.","''여덟''이라고 읽고, 숫자로는 8이에요.","센 것에 표시하며 세면 빠뜨리지 않아요."],"variant_rule":{"item":["🐜","⭐","🍓"],"n":[6,9],"range":[1,9]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_challenge#2','math',1,1,'u1','L02','g1_math_u1_L02_challenge','lesson_challenge','M1-1-C2',2,'mc','auto','''일곱''을 숫자로 바르게 쓴 것은 무엇인가요?',ARRAY['M02']::text[],false,'{"seq":2,"concept":"M1-1-C2","difficulty":2,"kind":"mc","stem":"''일곱''을 숫자로 바르게 쓴 것은 무엇인가요?","options":[{"t":"7","correct":true},{"t":"6","mis":"M02"},{"t":"8","mis":"M02"}],"explanation":["일곱은 숫자로 7이에요.","6은 여섯, 8은 여덟이에요.","읽는 말과 숫자를 짝지어 외워 두세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_challenge#3','math',1,1,'u1','L02','g1_math_u1_L02_challenge','lesson_challenge','M1-1-C2',3,'mc','auto','병아리 9마리가 있었어요. 지금 6마리가 보여요. 상자 뒤에 숨은 병아리는 몇 마리인가요?',ARRAY['M03']::text[],true,'{"seq":3,"concept":"M1-1-C2","difficulty":3,"kind":"mc","stem":"병아리 9마리가 있었어요. 지금 6마리가 보여요. 상자 뒤에 숨은 병아리는 몇 마리인가요?","asset":{"type":"hidden_group","item":"🐤","visible":6,"total":9},"options":[{"t":"3","correct":true},{"t":"6","mis":"M03"},{"t":"9","mis":"M03"}],"explanation":["보이는 6마리에서 일곱, 여덟, 아홉 — 3마리를 더 세면 9마리예요.","그래서 숨은 병아리는 3마리예요.","6은 보이는 수, 9는 전체 수예요."],"variant_rule":{"total":[6,9]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
