INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_challenge#5','math',1,1,'u1','L02','g1_math_u1_L02_challenge','lesson_challenge','M1-1-C2',3,'data','auto','과일 가게 그림표예요. 딸기 칸에는 🍓가 7개, 바나나 칸에는 🍌가 9개 있어요. 바나나는 몇 개인가요?',ARRAY['M01','M05']::text[],true,'{"seq":5,"concept":"M1-1-C2","difficulty":3,"kind":"data","stem":"과일 가게 그림표예요. 딸기 칸에는 🍓가 7개, 바나나 칸에는 🍌가 9개 있어요. 바나나는 몇 개인가요?","asset":{"type":"picto_table","rows":[{"label":"딸기","item":"🍓","n":7},{"label":"바나나","item":"🍌","n":9}]},"options":[{"t":"9","correct":true},{"t":"7","mis":"M05"},{"t":"8","mis":"M01"}],"explanation":["바나나 칸의 그림만 세어요 — 9개예요.","7은 딸기 칸의 수예요.","표에서는 어느 줄을 읽는지 손가락으로 짚으세요."],"variant_rule":{"items":[["🍓","🍌"],["🍎","🍉"],["🍪","🍩"]],"n":[6,9]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_challenge#6','math',1,1,'u1','L02','g1_math_u1_L02_challenge','lesson_challenge','M1-1-C2',3,'match','auto','같은 수끼리 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"M1-1-C2","difficulty":3,"kind":"match","stem":"같은 수끼리 이어 보세요.","pairs":[{"l":"6","r":"여섯"},{"l":"9","r":{"type":"dots","n":9}},{"l":"8","r":{"type":"dots","n":8}}],"explanation":["숫자와 말, 숫자와 점그림을 모두 이어요.","9는 아홉이고 점 아홉 개와 같아요.","말·숫자·그림은 같은 수를 다르게 나타낸 거예요."],"variant_rule":{"n_pool":[6,9],"pool":[6,7,8,9]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_challenge#7','math',1,1,'u1','L02','g1_math_u1_L02_challenge','lesson_challenge','M1-1-C2',3,'ox','auto','큰 수박 1개는 작은 딸기 7개보다 수가 많습니다.',ARRAY['M10']::text[],false,'{"seq":7,"concept":"M1-1-C2","difficulty":3,"kind":"ox","stem":"큰 수박 1개는 작은 딸기 7개보다 수가 많습니다.","answer":"X","reason_options":[{"t":"수는 크기가 아니라 개수라서","correct":true},{"t":"수박이 훨씬 크니까","mis":"M10"}],"explanation":["수박은 1개, 딸기는 7개예요.","크기가 커도 개수는 1개예요.","수를 비교할 때는 개수만 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_challenge#8','math',1,1,'u1','L02','g1_math_u1_L02_challenge','lesson_challenge','M1-1-C2',4,'sa','auto','점이 규칙대로 늘어나요. 다음 칸의 점은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M1-1-C2","difficulty":4,"kind":"sa","stem":"점이 규칙대로 늘어나요. 다음 칸의 점은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"rule","cells":[6,7,8]},"answer":["9"],"explanation":["점이 1개씩 늘어나는 규칙이에요.","6, 7, 8 다음이니까 9예요.","각 칸의 점을 세어 규칙을 먼저 찾아보세요."],"variant_rule":{"start":[5,6]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_challenge#9','math',1,1,'u1','L02','g1_math_u1_L02_challenge','lesson_challenge','M1-1-C2',4,'mc','auto','수수께끼예요. "나는 여섯 바로 다음 수이고, 여덟 바로 앞의 수예요." 나는 누구일까요?',ARRAY['M06']::text[],true,'{"seq":9,"concept":"M1-1-C2","difficulty":4,"kind":"mc","stem":"수수께끼예요. \"나는 여섯 바로 다음 수이고, 여덟 바로 앞의 수예요.\" 나는 누구일까요?","options":[{"t":"7","correct":true},{"t":"6","mis":"M06"},{"t":"8","mis":"M06"}],"explanation":["여섯 다음은 일곱이에요.","여덟 앞도 일곱이에요.","두 조건이 모두 맞는 수는 7이에요."],"variant_rule":{"n":[7,8]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L02_challenge#10','math',1,1,'u1','L02','g1_math_u1_L02_challenge','lesson_challenge','M1-1-C2',4,'essay','teacher','왼쪽 상자와 오른쪽 상자의 공은 모두 몇 개인가요? 숫자를 쓰고, 어떻게 세었는지 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-C2","difficulty":4,"kind":"essay","stem":"왼쪽 상자와 오른쪽 상자의 공은 모두 몇 개인가요? 숫자를 쓰고, 어떻게 세었는지 말해 보세요.","asset":{"type":"pair_boxes","left":4,"right":5},"answer_guide":{"answer":"9","scoring_points":["개수 9를 바르게 씀","이어 세기 등 세는 방법을 자기 말로 설명"]},"explanation":["왼쪽 4개에서 다섯, 여섯…아홉 — 모두 9개예요.","한꺼번에 세도 되고, 왼쪽부터 이어 세도 돼요.","어떻게 세었는지 말로 설명해 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_basic#1','math',1,1,'u1','L03','g1_math_u1_L03_basic','lesson_basic','M1-1-C3',1,'mc','auto','왼쪽에서 세면 표시된 것은 몇째인가요?',ARRAY['M04']::text[],true,'{"seq":1,"concept":"M1-1-C3","difficulty":1,"kind":"mc","stem":"왼쪽에서 세면 표시된 것은 몇째인가요?","asset":{"type":"ordinal_row","items":["🐶","🐱","🐰","🐻","🦊"],"dir":"right","mark":2},"options":[{"t":"둘째","correct":true},{"t":"셋째","mis":"M04"},{"t":"첫째","mis":"M04"}],"explanation":["왼쪽부터 첫째, 둘째 하고 세어요.","표시된 것은 둘째예요.","둘째는 한 개를 가리키는 말이에요 — 2개와 달라요."],"variant_rule":{"ordinal":{"ask":"position","items":["🐶","🐱","🐰","🐻","🦊","🐼","🐯","🐨","🦁"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_basic#2','math',1,1,'u1','L03','g1_math_u1_L03_basic','lesson_basic','M1-1-C3',1,'mc','auto','왼쪽에서 셋째에 있는 것은 무엇인가요?',ARRAY['M05']::text[],true,'{"seq":2,"concept":"M1-1-C3","difficulty":1,"kind":"mc","stem":"왼쪽에서 셋째에 있는 것은 무엇인가요?","asset":{"type":"ordinal_row","items":["🐶","🐱","🐰","🐻","🦊"],"dir":"right"},"options":[{"t":"🐰","correct":true},{"t":"🐱","mis":"M05"},{"t":"🐻","mis":"M05"}],"explanation":["왼쪽부터 첫째, 둘째, 셋째 하고 세어요.","셋째는 🐰예요.","어느 쪽에서 세는지 먼저 확인하세요."],"variant_rule":{"ordinal":{"ask":"which","items":["🐶","🐱","🐰","🐻","🦊","🐼","🐯","🐨","🦁"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_basic#3','math',1,1,'u1','L03','g1_math_u1_L03_basic','lesson_basic','M1-1-C3',1,'mc','auto','오른쪽에서 첫째에 있는 것은 무엇인가요?',ARRAY['M05']::text[],false,'{"seq":3,"concept":"M1-1-C3","difficulty":1,"kind":"mc","stem":"오른쪽에서 첫째에 있는 것은 무엇인가요?","asset":{"type":"ordinal_row","items":["🐶","🐱","🐰","🐻","🦊"],"dir":"right"},"options":[{"t":"🦊","correct":true},{"t":"🐶","mis":"M05"},{"t":"🐰","mis":"M05"}],"explanation":["이번에는 오른쪽부터 세요.","오른쪽 끝에 있는 🦊가 첫째예요.","기준이 바뀌면 답도 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_basic#4','math',1,1,'u1','L03','g1_math_u1_L03_basic','lesson_basic','M1-1-C3',1,'mc','auto','순서를 나타내는 말이에요. 빈칸에 알맞은 말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_basic#5','math',1,1,'u1','L03','g1_math_u1_L03_basic','lesson_basic','M1-1-C3',2,'mc','auto','''셋째''와 ''3개''는 어떻게 다른가요?',ARRAY['M04']::text[],false,'{"seq":5,"concept":"M1-1-C3","difficulty":2,"kind":"mc","stem":"''셋째''와 ''3개''는 어떻게 다른가요?","options":[{"t":"셋째는 한 개, 3개는 세 개를 뜻해요","correct":true},{"t":"둘은 똑같은 말이에요","mis":"M04"},{"t":"셋째가 3개보다 많아요","mis":"M04"}],"explanation":["셋째는 순서를 나타내요 — 딱 한 개를 가리켜요.","3개는 개수를 나타내요 — 모두 세 개예요.","그림에 동그라미를 쳐서 비교해 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_basic#6','math',1,1,'u1','L03','g1_math_u1_L03_basic','lesson_basic','M1-1-C3',2,'sa','auto','친구 6명이 한 줄로 섰어요. 지우는 앞에서 넷째예요. 지우 앞에는 몇 명이 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M1-1-C3","difficulty":2,"kind":"sa","stem":"친구 6명이 한 줄로 섰어요. 지우는 앞에서 넷째예요. 지우 앞에는 몇 명이 있나요? 숫자로 쓰세요.","answer":["3"],"explanation":["지우가 넷째니까 앞에는 첫째, 둘째, 셋째 — 3명이에요.","넷째인 지우는 세지 않아요.","줄을 그려서 지우 자리에 표시해 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_basic#7','math',1,1,'u1','L03','g1_math_u1_L03_basic','lesson_basic','M1-1-C3',2,'mc','auto','오른쪽에서 셋째에 있는 것은 무엇인가요?',ARRAY['M05']::text[],false,'{"seq":7,"concept":"M1-1-C3","difficulty":2,"kind":"mc","stem":"오른쪽에서 셋째에 있는 것은 무엇인가요?","asset":{"type":"ordinal_row","items":["🐶","🐱","🐰","🐻","🦊"],"dir":"right"},"options":[{"t":"🐰","correct":true},{"t":"🐻","mis":"M05"},{"t":"🐱","mis":"M05"}],"explanation":["오른쪽 끝부터 첫째, 둘째, 셋째 하고 세어요.","🦊, 🐻, 🐰 순서니까 🐰예요.","왼쪽에서 셋째와 답이 다를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_basic#8','math',1,1,'u1','L03','g1_math_u1_L03_basic','lesson_basic','M1-1-C3',2,'ox','auto','이 그림에서 🐻는 왼쪽에서 넷째입니다.',ARRAY['M05']::text[],false,'{"seq":8,"concept":"M1-1-C3","difficulty":2,"kind":"ox","stem":"이 그림에서 🐻는 왼쪽에서 넷째입니다.","asset":{"type":"ordinal_row","items":["🐶","🐱","🐰","🐻","🦊"],"dir":"right"},"answer":"O","reason_options":[{"t":"왼쪽부터 첫째, 둘째, 셋째, 넷째로 세어서","correct":true},{"t":"🐻가 크게 보여서","mis":"M05"}],"explanation":["왼쪽부터 세면 🐶, 🐱, 🐰, 🐻 — 🐻는 넷째예요.","맞는 말이에요.","순서를 셀 때는 기준 쪽부터 하나씩 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_basic#9','math',1,1,'u1','L03','g1_math_u1_L03_basic','lesson_basic','M1-1-C3',2,'mc','auto','보라가 사물함에 스티커를 붙였어요. "왼쪽에서 다섯째 칸"은 몇 칸을 뜻하나요?',ARRAY['M04']::text[],false,'{"seq":9,"concept":"M1-1-C3","difficulty":2,"kind":"mc","stem":"보라가 사물함에 스티커를 붙였어요. \"왼쪽에서 다섯째 칸\"은 몇 칸을 뜻하나요?","options":[{"t":"한 칸","correct":true},{"t":"다섯 칸","mis":"M04"},{"t":"네 칸","mis":"M04"}],"explanation":["다섯째는 순서를 나타내는 말이에요.","딱 한 칸만 가리켜요.","''다섯 칸''은 개수라서 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_basic#10','math',1,1,'u1','L03','g1_math_u1_L03_basic','lesson_basic','M1-1-C3',3,'error','auto','민수는 "왼쪽에서 셋째"를 찾으라는 문제에서 오른쪽 끝부터 세어 답을 골랐어요. 민수는 무엇을 잘못했나요?',ARRAY['M02','M04']::text[],false,'{"seq":10,"concept":"M1-1-C3","difficulty":3,"kind":"error","stem":"민수는 \"왼쪽에서 셋째\"를 찾으라는 문제에서 오른쪽 끝부터 세어 답을 골랐어요. 민수는 무엇을 잘못했나요?","options":[{"t":"세는 기준 방향을 잘못 잡았어요","correct":true,"mis_target":"M05"},{"t":"개수를 잘못 세었어요","mis":"M04"},{"t":"순서 말을 잘못 읽었어요","mis":"M02"}],"explanation":["문제는 왼쪽에서 세라고 했어요.","민수는 오른쪽에서 세어서 자리가 달라졌어요.","세기 전에 화살표로 기준 방향을 먼저 표시하세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_challenge#1','math',1,1,'u1','L03','g1_math_u1_L03_challenge','lesson_challenge','M1-1-C3',2,'mc','auto','왼쪽에서 여섯째에 있는 것은 무엇인가요?',ARRAY['M05']::text[],true,'{"seq":1,"concept":"M1-1-C3","difficulty":2,"kind":"mc","stem":"왼쪽에서 여섯째에 있는 것은 무엇인가요?","asset":{"type":"ordinal_row","items":["🐶","🐱","🐰","🐻","🦊","🐼","🐯"],"dir":"right"},"options":[{"t":"🐼","correct":true},{"t":"🦊","mis":"M05"},{"t":"🐯","mis":"M05"}],"explanation":["왼쪽부터 여섯 번 세어요.","여섯째는 🐼예요.","다섯째·일곱째와 헷갈리면 손가락으로 짚으세요."],"variant_rule":{"ordinal":{"ask":"which","items":["🐶","🐱","🐰","🐻","🦊","🐼","🐯","🐨","🦁"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_challenge#2','math',1,1,'u1','L03','g1_math_u1_L03_challenge','lesson_challenge','M1-1-C3',2,'sa','auto','친구 7명이 줄을 섰어요. 하늘이는 앞에서 다섯째예요. 하늘이 뒤에는 몇 명이 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M1-1-C3","difficulty":2,"kind":"sa","stem":"친구 7명이 줄을 섰어요. 하늘이는 앞에서 다섯째예요. 하늘이 뒤에는 몇 명이 있나요? 숫자로 쓰세요.","answer":["2"],"explanation":["앞에서 다섯째면 앞에 4명, 하늘이가 1명이에요.","7명에서 5명을 빼면 뒤에는 2명이에요.","줄을 그리고 하늘이 자리에 표시해 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_challenge#3','math',1,1,'u1','L03','g1_math_u1_L03_challenge','lesson_challenge','M1-1-C3',3,'mc','auto','친구 8명이 줄을 섰어요. 앞에서 셋째인 사람은 뒤에서 몇째인가요?',ARRAY['M04','M05']::text[],false,'{"seq":3,"concept":"M1-1-C3","difficulty":3,"kind":"mc","stem":"친구 8명이 줄을 섰어요. 앞에서 셋째인 사람은 뒤에서 몇째인가요?","options":[{"t":"여섯째","correct":true},{"t":"셋째","mis":"M05"},{"t":"다섯째","mis":"M04"}],"explanation":["앞에서 셋째면 앞에 2명, 뒤에 5명이에요.","뒤에서 세면 첫째부터 여섯째가 돼요.","줄을 그려 두 방향으로 각각 세어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_challenge#4','math',1,1,'u1','L03','g1_math_u1_L03_challenge','lesson_challenge','M1-1-C3',3,'error','auto','지우는 "앞에서 넷째인 친구에게 색종이를 주세요"라는 말을 듣고 앞에서부터 4명에게 나누어 주었어요. 지우는 무엇을 잘못했나요?',ARRAY['M01','M05']::text[],false,'{"seq":4,"concept":"M1-1-C3","difficulty":3,"kind":"error","stem":"지우는 \"앞에서 넷째인 친구에게 색종이를 주세요\"라는 말을 듣고 앞에서부터 4명에게 나누어 주었어요. 지우는 무엇을 잘못했나요?","options":[{"t":"넷째(순서)를 4개(개수)로 생각했어요","correct":true,"mis_target":"M04"},{"t":"세는 방향을 반대로 했어요","mis":"M05"},{"t":"색종이를 잘못 세었어요","mis":"M01"}],"explanation":["넷째는 딱 한 사람을 가리켜요.","4명은 개수라서 뜻이 달라요.","순서 말인지 개수 말인지 먼저 구분하세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_challenge#5','math',1,1,'u1','L03','g1_math_u1_L03_challenge','lesson_challenge','M1-1-C3',3,'data','auto','달리기 순서를 그림표로 나타냈어요. 첫째 줄에는 🏃가 1개, 둘째 줄에는 🏃가 2개 그려져 있어요. 둘째 줄은 몇 개인가요?',ARRAY['M01','M05']::text[],false,'{"seq":5,"concept":"M1-1-C3","difficulty":3,"kind":"data","stem":"달리기 순서를 그림표로 나타냈어요. 첫째 줄에는 🏃가 1개, 둘째 줄에는 🏃가 2개 그려져 있어요. 둘째 줄은 몇 개인가요?","asset":{"type":"picto_table","rows":[{"label":"첫째 줄","item":"🏃","n":1},{"label":"둘째 줄","item":"🏃","n":2}]},"options":[{"t":"2","correct":true},{"t":"1","mis":"M05"},{"t":"3","mis":"M01"}],"explanation":["둘째 줄의 그림만 세어요 — 2개예요.","1은 첫째 줄의 수예요.","표에서는 읽을 줄을 손가락으로 짚으세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_challenge#6','math',1,1,'u1','L03','g1_math_u1_L03_challenge','lesson_challenge','M1-1-C3',3,'mc','auto','왼쪽에서 둘째에 있는 것과 오른쪽에서 둘째에 있는 것은 무엇인가요?',ARRAY['M05']::text[],false,'{"seq":6,"concept":"M1-1-C3","difficulty":3,"kind":"mc","stem":"왼쪽에서 둘째에 있는 것과 오른쪽에서 둘째에 있는 것은 무엇인가요?","asset":{"type":"ordinal_row","items":["🐶","🐱","🐰","🐻","🦊"],"dir":"right"},"options":[{"t":"🐱와 🐻","correct":true},{"t":"🐱와 🐰","mis":"M05"},{"t":"🐶와 🦊","mis":"M05"}],"explanation":["왼쪽부터 둘째는 🐱예요.","오른쪽부터 둘째는 🐻예요.","기준이 다르면 가리키는 것도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_challenge#7','math',1,1,'u1','L03','g1_math_u1_L03_challenge','lesson_challenge','M1-1-C3',3,'ox','auto','줄의 맨 앞에 선 사람은 ''첫째''이면서 동시에 ''1명''입니다.',ARRAY['M04']::text[],false,'{"seq":7,"concept":"M1-1-C3","difficulty":3,"kind":"ox","stem":"줄의 맨 앞에 선 사람은 ''첫째''이면서 동시에 ''1명''입니다.","answer":"X","reason_options":[{"t":"첫째는 순서, 1명은 개수라서 뜻이 달라요","correct":true},{"t":"맨 앞이니까 둘 다 맞아요","mis":"M04"}],"explanation":["첫째는 자리를 나타내는 말이에요.","1명은 사람 수를 나타내는 말이에요.","같은 사람을 가리켜도 말의 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_challenge#8','math',1,1,'u1','L03','g1_math_u1_L03_challenge','lesson_challenge','M1-1-C3',4,'sa','auto','친구 9명이 줄을 섰어요. 보라는 뒤에서 셋째예요. 보라는 앞에서 몇째인가요? 숫자로 쓰세요. (예: 일곱째면 7)','{}'::text[],false,'{"seq":8,"concept":"M1-1-C3","difficulty":4,"kind":"sa","stem":"친구 9명이 줄을 섰어요. 보라는 뒤에서 셋째예요. 보라는 앞에서 몇째인가요? 숫자로 쓰세요. (예: 일곱째면 7)","answer":["7"],"explanation":["뒤에서 셋째면 뒤에 2명이 있어요.","9명 중 보라 뒤 2명을 빼면 보라는 일곱째예요.","줄을 그리고 양쪽에서 각각 세어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_challenge#9','math',1,1,'u1','L03','g1_math_u1_L03_challenge','lesson_challenge','M1-1-C3',4,'mc','auto','수수께끼예요. "나는 왼쪽에서 넷째이고, 오른쪽에서 둘째예요. 줄에는 모두 몇 명이 있을까요?"',ARRAY['M04']::text[],false,'{"seq":9,"concept":"M1-1-C3","difficulty":4,"kind":"mc","stem":"수수께끼예요. \"나는 왼쪽에서 넷째이고, 오른쪽에서 둘째예요. 줄에는 모두 몇 명이 있을까요?\"","options":[{"t":"5명","correct":true},{"t":"6명","mis":"M04"},{"t":"4명","mis":"M04"}],"explanation":["왼쪽에서 넷째면 앞에 3명이 있어요.","오른쪽에서 둘째면 뒤에 1명이 있어요.","3명 + 나 + 1명 = 모두 5명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L03_challenge#10','math',1,1,'u1','L03','g1_math_u1_L03_challenge','lesson_challenge','M1-1-C3',4,'essay','teacher','줄을 선 그림에서 🐰가 몇째인지 쓰고, 어느 쪽에서 세었는지 함께 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-1-C3","difficulty":4,"kind":"essay","stem":"줄을 선 그림에서 🐰가 몇째인지 쓰고, 어느 쪽에서 세었는지 함께 말해 보세요.","asset":{"type":"ordinal_row","items":["🐶","🐱","🐰","🐻","🦊"],"dir":"right","mark":3},"answer_guide":{"answer":"왼쪽에서 셋째 (또는 오른쪽에서 셋째)","scoring_points":["순서를 바르게 말함","어느 쪽에서 세었는지 기준을 밝힘"]},"explanation":["왼쪽부터 세면 🐰는 셋째예요.","오른쪽부터 세어도 셋째예요.","기준을 함께 말해야 듣는 사람이 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L04_basic#1','math',1,1,'u1','L04','g1_math_u1_L04_basic','lesson_basic','M1-1-C4',1,'mc','auto','수를 순서대로 늘어놓았어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M06']::text[],true,'{"seq":1,"concept":"M1-1-C4","difficulty":1,"kind":"mc","stem":"수를 순서대로 늘어놓았어요. 빈칸에 알맞은 수는 무엇인가요?","asset":{"type":"number_line","cells":["1","2","3",null,"5","6"]},"options":[{"t":"4","correct":true},{"t":"5","mis":"M06"},{"t":"3","mis":"M06"}],"explanation":["1, 2, 3 다음은 4예요.","순서대로 세면 3 바로 뒤가 4예요.","배열판을 손가락으로 짚으며 세어 보세요."],"variant_rule":{"seqline":{"from":1,"max":9,"len":6,"dir":"up"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L04_basic#2','math',1,1,'u1','L04','g1_math_u1_L04_basic','lesson_basic','M1-1-C4',1,'mc','auto','6 바로 다음의 수는 무엇인가요?',ARRAY['M06']::text[],false,'{"seq":2,"concept":"M1-1-C4","difficulty":1,"kind":"mc","stem":"6 바로 다음의 수는 무엇인가요?","asset":{"type":"number_line","cells":["1","2","3","4","5","6","7","8","9"],"mark":6},"options":[{"t":"7","correct":true},{"t":"5","mis":"M06"},{"t":"8","mis":"M06"}],"explanation":["순서대로 세면 6 다음은 7이에요.","5는 6 바로 앞의 수예요.","1부터 소리 내어 세어 확인해 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L04_basic#3','math',1,1,'u1','L04','g1_math_u1_L04_basic','lesson_basic','M1-1-C4',1,'sa','auto','수를 순서대로 늘어놓았어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-1-C4","difficulty":1,"kind":"sa","stem":"수를 순서대로 늘어놓았어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","asset":{"type":"number_line","cells":["4","5","6",null,"8","9"]},"answer":["7"],"explanation":["5, 6 다음은 7이에요.","7 다음은 8, 9로 이어져요.","배열판을 짚으며 이어 세어 보세요."],"variant_rule":{"seqline":{"from":1,"max":9,"len":6,"dir":"up"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L04_basic#4','math',1,1,'u1','L04','g1_math_u1_L04_basic','lesson_basic','M1-1-C4',1,'mc','auto','9부터 거꾸로 세면 9 다음에 오는 수는 무엇인가요?',ARRAY['M06']::text[],false,'{"seq":4,"concept":"M1-1-C4","difficulty":1,"kind":"mc","stem":"9부터 거꾸로 세면 9 다음에 오는 수는 무엇인가요?","asset":{"type":"number_line","cells":["1","2","3","4","5","6","7","8","9"],"mark":9},"options":[{"t":"8","correct":true},{"t":"7","mis":"M06"},{"t":"9","mis":"M06"}],"explanation":["거꾸로 세면 9, 8, 7… 이에요.","9 다음은 8이에요.","배열판에서 왼쪽으로 한 칸 가면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L04_basic#5','math',1,1,'u1','L04','g1_math_u1_L04_basic','lesson_basic','M1-1-C4',2,'mc','auto','수를 거꾸로 늘어놓았어요. 빈칸에 알맞은 수는 무엇인가요?',ARRAY['M06']::text[],true,'{"seq":5,"concept":"M1-1-C4","difficulty":2,"kind":"mc","stem":"수를 거꾸로 늘어놓았어요. 빈칸에 알맞은 수는 무엇인가요?","asset":{"type":"number_line","cells":["9","8","7",null,"5","4"]},"options":[{"t":"6","correct":true},{"t":"8","mis":"M06"},{"t":"5","mis":"M06"}],"explanation":["9, 8, 7 다음은 6이에요.","거꾸로 세면 하나씩 작아져요.","오른쪽에서 왼쪽으로 짚으며 세어 보세요."],"variant_rule":{"seqline":{"from":1,"max":9,"len":6,"dir":"down"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L04_basic#6','math',1,1,'u1','L04','g1_math_u1_L04_basic','lesson_basic','M1-1-C4',2,'sa','auto','3부터 이어 세어 보세요. 3, 4, 5, 6 다음에 오는 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M1-1-C4","difficulty":2,"kind":"sa","stem":"3부터 이어 세어 보세요. 3, 4, 5, 6 다음에 오는 수를 숫자로 쓰세요.","answer":["7"],"explanation":["3에서 시작해 하나씩 이어 세면 7이에요.","6 바로 다음이 7이에요.","손가락을 하나씩 펴며 이어 세어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L04_basic#7','math',1,1,'u1','L04','g1_math_u1_L04_basic','lesson_basic','M1-1-C4',2,'mc','auto','5와 7 사이에 있는 수는 무엇인가요?',ARRAY['M06']::text[],false,'{"seq":7,"concept":"M1-1-C4","difficulty":2,"kind":"mc","stem":"5와 7 사이에 있는 수는 무엇인가요?","asset":{"type":"number_line","cells":["1","2","3","4","5","6","7","8","9"]},"options":[{"t":"6","correct":true},{"t":"4","mis":"M06"},{"t":"8","mis":"M06"}],"explanation":["5 다음, 7 앞에 있는 수를 찾아요.","5, 6, 7 — 사이에 있는 수는 6이에요.","배열판에서 두 수 사이를 짚어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L04_basic#8','math',1,1,'u1','L04','g1_math_u1_L04_basic','lesson_basic','M1-1-C4',2,'ox','auto','수를 순서대로 세면 7 다음은 8입니다.',ARRAY['M10']::text[],false,'{"seq":8,"concept":"M1-1-C4","difficulty":2,"kind":"ox","stem":"수를 순서대로 세면 7 다음은 8입니다.","answer":"O","reason_options":[{"t":"1부터 순서대로 세면 7 다음이 8이라서","correct":true},{"t":"8이 더 크게 생겨서","mis":"M10"}],"explanation":["순서대로 세면 7 다음은 8이에요.","맞는 말이에요.","배열판에서 오른쪽으로 한 칸이 다음 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L04_basic#9','math',1,1,'u1','L04','g1_math_u1_L04_basic','lesson_basic','M1-1-C4',2,'mc','auto','수를 큰 것부터 순서대로 늘어놓은 것은 무엇인가요?',ARRAY['M06']::text[],false,'{"seq":9,"concept":"M1-1-C4","difficulty":2,"kind":"mc","stem":"수를 큰 것부터 순서대로 늘어놓은 것은 무엇인가요?","options":[{"t":"9 — 8 — 7 — 6","correct":true},{"t":"6 — 7 — 8 — 9","mis":"M06"},{"t":"9 — 7 — 8 — 6","mis":"M06"}],"explanation":["큰 것부터면 거꾸로 세는 순서예요.","9, 8, 7, 6이 맞아요.","작은 것부터는 6, 7, 8, 9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
