INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L04_challenge#1','math',1,1,'u1','L04','g1_math_u1_L04_challenge','lesson_challenge','M1-1-C4',2,'sa','auto','수를 순서대로 늘어놓았어요. 빈칸에 알맞은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-1-C4","difficulty":2,"kind":"sa","stem":"수를 순서대로 늘어놓았어요. 빈칸에 알맞은 수를 숫자로 쓰세요.","asset":{"type":"number_line","cells":["4","5",null,"7","8","9"]},"answer":["6"],"explanation":["4, 5 다음은 6이에요.","6 다음은 7로 이어져요.","배열판을 짚으며 세어 보세요."],"variant_rule":{"seqline":{"from":1,"max":9,"len":6,"dir":"up"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L04_challenge#2','math',1,1,'u1','L04','g1_math_u1_L04_challenge','lesson_challenge','M1-1-C4',2,'mc','auto','2 바로 앞의 수는 무엇인가요?',ARRAY['M06','M07']::text[],false,'{"seq":2,"concept":"M1-1-C4","difficulty":2,"kind":"mc","stem":"2 바로 앞의 수는 무엇인가요?","asset":{"type":"number_line","cells":["1","2","3","4","5","6","7","8","9"],"mark":2},"options":[{"t":"1","correct":true},{"t":"3","mis":"M07"},{"t":"2","mis":"M06"}],"explanation":["앞의 수는 왼쪽에 있는 수예요.","2 바로 앞은 1이에요.","3은 2 바로 뒤의 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L04_challenge#3','math',1,1,'u1','L04','g1_math_u1_L04_challenge','lesson_challenge','M1-1-C4',3,'mc','auto','7부터 거꾸로 세었어요. 7, 6, 5 다음에 오는 두 수는 무엇인가요?',ARRAY['M06']::text[],false,'{"seq":3,"concept":"M1-1-C4","difficulty":3,"kind":"mc","stem":"7부터 거꾸로 세었어요. 7, 6, 5 다음에 오는 두 수는 무엇인가요?","options":[{"t":"4, 3","correct":true},{"t":"6, 7","mis":"M06"},{"t":"4, 5","mis":"M06"}],"explanation":["거꾸로 세면 하나씩 작아져요.","5 다음은 4, 그 다음은 3이에요.","배열판에서 왼쪽으로 한 칸씩 가세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
