INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L07_basic#5','math',1,1,'u1','L07','g1_math_u1_L07_basic','lesson_basic','M1-1-C7',2,'mc','auto','연필과 지우개를 하나씩 짝지었더니 연필이 2개 남았어요. 무엇이 더 많은가요?',ARRAY['M10','M11']::text[],false,'{"seq":5,"concept":"M1-1-C7","difficulty":2,"kind":"mc","stem":"연필과 지우개를 하나씩 짝지었더니 연필이 2개 남았어요. 무엇이 더 많은가요?","options":[{"t":"연필","correct":true},{"t":"지우개","mis":"M11"},{"t":"수가 같아요","mis":"M10"}],"explanation":["짝짓고 남은 쪽이 더 많아요.","연필이 남았으니 연필이 더 많아요.","일대일로 짝지어 비교하면 정확해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L07_basic#6','math',1,1,'u1','L07','g1_math_u1_L07_basic','lesson_basic','M1-1-C7',2,'sa','auto','🐟가 7마리, 🐤가 4마리 있어요. 더 많은 것의 수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M1-1-C7","difficulty":2,"kind":"sa","stem":"🐟가 7마리, 🐤가 4마리 있어요. 더 많은 것의 수를 숫자로 쓰세요.","asset":{"type":"compare_groups","rows":[{"label":"물고기","item":"🐟","n":7},{"label":"병아리","item":"🐤","n":4}]},"answer":["7"],"explanation":["물고기 7마리, 병아리 4마리예요.","7이 4보다 커요.","더 많은 것의 수는 7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
