INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L07_basic#8','math',1,1,'u1','L07','g1_math_u1_L07_basic','lesson_basic','M1-1-C7',2,'ox','auto','큰 접시에 담긴 쿠키 3개는 작은 접시에 담긴 쿠키 5개보다 많습니다.',ARRAY['M10']::text[],false,'{"seq":8,"concept":"M1-1-C7","difficulty":2,"kind":"ox","stem":"큰 접시에 담긴 쿠키 3개는 작은 접시에 담긴 쿠키 5개보다 많습니다.","answer":"X","reason_options":[{"t":"수는 그릇 크기가 아니라 개수로 비교해서","correct":true},{"t":"접시가 크니까 더 많아요","mis":"M10"}],"explanation":["쿠키는 3개와 5개예요.","5개가 더 많아요.","그릇 크기가 아니라 개수를 세세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
