INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_math_u1_L07_basic#10','math',1,1,'u1','L07','g1_math_u1_L07_basic','lesson_basic','M1-1-C7',3,'error','auto','민수가 사탕을 길게 늘어놓은 줄과 짧게 모아 놓은 줄을 보고 "긴 줄이 더 많아"라고 말했어요. 세어 보니 긴 줄은 4개, 짧은 줄은 6개였어요. 민수는 무엇을 잘못했나요?',ARRAY['M01','M10']::text[],false,'{"seq":10,"concept":"M1-1-C7","difficulty":3,"kind":"error","stem":"민수가 사탕을 길게 늘어놓은 줄과 짧게 모아 놓은 줄을 보고 \"긴 줄이 더 많아\"라고 말했어요. 세어 보니 긴 줄은 4개, 짧은 줄은 6개였어요. 민수는 무엇을 잘못했나요?","options":[{"t":"개수가 아니라 늘어선 길이로 비교했어요","correct":true,"mis_target":"M10"},{"t":"사탕을 빠뜨리고 세었어요","mis":"M01"},{"t":"정말 긴 줄이 많아요","mis":"M10"}],"explanation":["줄이 길어도 개수가 적을 수 있어요.","세어 보면 4개보다 6개가 많아요.","하나씩 짝지어 비교해 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
